python3 << 'EOF'
import json

# Note to MIDI conversion
notes = {
    'C2': 36, 'D2': 38, 'E2': 40, 'F2': 41, 'G2': 43, 'A2': 45, 'B2': 47,
    'C3': 48, 'D3': 50, 'E3': 52, 'F3': 53, 'G3': 55, 'A3': 57, 'B3': 59,
    'C4': 60, 'D4': 62, 'E4': 64, 'F4': 65, 'G4': 67, 'A4': 69, 'B4': 71,
    'C5': 72, 'D5': 74, 'E5': 76, 'F5': 77, 'G5': 79, 'A5': 81, 'B5': 83,
    'C6': 84, 'D6': 86, 'E6': 88, 'F6': 89, 'G6': 91
}

# Create batch for pattern data
batch = []

# Pattern 0: Intro melody
# Lead on channel 0 (instrument 1)
melody_0 = [
    (0, 'C5', 1, 64), (2, None, 0, 0), (3, 'G4', 1, 64), (4, None, 0, 0), 
    (5, 'E4', 1, 64), (7, None, 0, 0), (8, 'G4', 1, 64),
    (10, 'C5', 1, 64), (12, None, 0, 0), (13, 'A4', 1, 64), (14, None, 0, 0),
    (15, 'F4', 1, 64), (17, None, 0, 0), (18, 'A4', 1, 64),
    (20, 'D5', 1, 64), (22, None, 0, 0), (23, 'B4', 1, 64), (24, None, 0, 0),
    (25, 'G4', 1, 64), (27, None, 0, 0), (28, 'B4', 1, 64),
    (30, 'E5', 1, 64), (32, None, 0, 0), (33, 'C5', 1, 64), (34, None, 0, 0),
    (35, 'A4', 1, 64), (37, None, 0, 0), (38, 'C5', 1, 64),
]

for row, note, inst, vol in melody_0:
    if note and note in notes:
        batch.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 0, "row": row, "channel": 0, "note": notes[note], "instrument": inst, "volume": vol}
        })

# Bass on channel 1 (instrument 2)
bass_notes_0 = [
    (0, 'C2', 2, 53), (4, None, 0, 0), (8, 'C2', 2, 53), (12, None, 0, 0),
    (16, 'F2', 2, 53), (20, None, 0, 0), (24, 'F2', 2, 53), (28, None, 0, 0),
    (32, 'G2', 2, 53), (36, None, 0, 0), (40, 'G2', 2, 53), (44, None, 0, 0),
    (48, 'A2', 2, 53), (52, None, 0, 0), (56, 'A2', 2, 53), (60, None, 0, 0),
]

for row, note, inst, vol in bass_notes_0:
    if note and note in notes:
        batch.append({
            "name": "pattern_set_cell",
            "arguments": {"pattern": 0, "row": row, "channel": 1, "note": notes[note], "instrument": inst, "volume": vol}
        })

# Drums on channels 2-4
# Kick on channel 2 (instrument 4)
drum_kick = [
    (0, 'C2', 4, 64), (8, 'C2', 4, 64), (16, 'C2', 4, 64), (24, 'C2', 4, 64),
    (32, 'C2', 4, 64), (40, 'C2', 4, 64), (48, 'C2', 4, 64), (56, 'C2', 4, 64),
]
for row, note, inst, vol in drum_kick:
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 0, "row": row, "channel": 2, "note": notes[note], "instrument": inst, "volume": vol}
    })

# Snare on channel 3 (instrument 5)
drum_snare = [
    (4, 'C3', 5, 53), (12, 'C3', 5, 53), (20, 'C3', 5, 53), (28, 'C3', 5, 53),
    (36, 'C3', 5, 53), (44, 'C3', 5, 53), (52, 'C3', 5, 53), (60, 'C3', 5, 53),
]
for row, note, inst, vol in drum_snare:
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 0, "row": row, "channel": 3, "note": notes[note], "instrument": inst, "volume": vol}
    })

# Hi-hat on channel 4 (instrument 6)
for row in range(0, 64, 2):
    batch.append({
        "name": "pattern_set_cell",
        "arguments": {"pattern": 0, "row": row, "channel": 4, "note": notes['C4'], "instrument": 6, "volume": 32}
    })

print(f"Created batch with {len(batch)} commands for pattern 0")

# Save to file
with open('/workspace/submission/batch_pattern0.json', 'w') as f:
    json.dump(batch, f)
print("Saved to /workspace/submission/batch_pattern0.json")
EOF
